            )
        ).scalar() or 0

        if inactive > 0:
            recommendations.append({
                'type': 'info',
                'message': (
                    f'👥 {inactive} clientes no han comprado '
                    f'en los últimos 30 días.'
                )
            })

        return {
            'recommendations': recommendations,
            'count': len(recommendations)
        }

